before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <ranges>
#include <vector>
int main() {
    std::vector<int> values{1, 2, 3};
    auto selected = values
        | std::views::filter([](int x) { return x > 1; })
        | std::views::transform([](int x) { return x * 10; });
    for (int value : selected) std::cout << value << ' ';
    std::cout << '\n';
}

```

after:
Follow each source value through the filter before the transform.

```cpp
#include <iostream>
#include <ranges>
#include <vector>
